// src/QueryBox.vue
<script setup>
import { ref, watch, onBeforeUnmount } from 'vue';
const props = defineProps({ modelValue: { type: String, required: true } });
const emit = defineEmits(['update:modelValue']);
const draft = ref(props.modelValue);
let timer = null;
function cancelPending() {
  if (timer !== null) { clearTimeout(timer); timer = null; }
}
function onInput(event) {
  draft.value = event.target.value;
  cancelPending();
  const value = draft.value;
  timer = setTimeout(() => {
    timer = null;
    emit('update:modelValue', value);
  }, 300);
}
watch(() => props.modelValue, value => {
  draft.value = value;
});
onBeforeUnmount(cancelPending);
</script>
<template><input :value="draft" @input="onInput" /></template>

// src/SearchPage.vue
<script setup>
import { ref, watch, onBeforeUnmount } from 'vue';
import QueryBox from './QueryBox.vue';
import { loadRows } from './api';
const query = ref('seed');
const category = ref('all');
const page = ref(1);
const rows = ref([]);
const cache = new Map();
let generation = 0;
async function reload() {
  const current = ++generation;
  const params = { category: category.value, query: query.value, page: page.value };
  if (params.query === '') { rows.value = []; return; }
  const key = JSON.stringify([params.category, params.query, params.page]);
  if (cache.has(key)) { rows.value = cache.get(key); return; }
  const result = await loadRows(params);
  if (current !== generation) { return; }
  cache.set(key, result);
  rows.value = result;
}
function reset() {
  query.value = '';
  category.value = 'all';
  page.value = 1;
  rows.value = [];
}
watch([query, category, page], reload, { immediate: true });
onBeforeUnmount(() => { generation += 1; });
</script>
<template>
  <QueryBox v-model="query" />
  <select v-model="category"><option value="all">全部</option><option value="guide">指南</option></select>
  <button @click="page += 1">下一页</button>
  <button @click="reset">重置</button>
  <p>{{ category }} / {{ query }} / {{ page }}</p>
  <ul><li v-for="row in rows" :key="row">{{ row }}</li></ul>
</template>
